59	static int test_chacha20poly1305(volatile csr_vp_t* csr) {
60	   // Test vectors
61	   uint8_t key[32] = {
62	      0x80, 0x81, 0x82, 0x83, 0x84, 0x85, 0x86, 0x87,
63	      0x88, 0x89, 0x8a, 0x8b, 0x8c, 0x8d, 0x8e, 0x8f,
64	      0x90, 0x91, 0x92, 0x93, 0x94, 0x95, 0x96, 0x97,
65	      0x98, 0x99, 0x9a, 0x9b, 0x9c, 0x9d, 0x9e, 0x9f};
66	
67	   uint8_t nonce[12] = {
68	      0x07, 0x00, 0x00, 0x00, 0x40, 0x41, 0x42, 0x43,
69	      0x44, 0x45, 0x46, 0x47};
70	
71	   const char *aad_str = "Additional authenticated data";
72	   uint8_t *aad = (uint8_t *)aad_str;
73	   size_t aad_len = strlen(aad_str);
74	
75	   const char *plaintext_str = "Hello CHILIChips - Wireguard team, let's test this aead!";
76	   uint8_t *plaintext = (uint8_t *)plaintext_str;
77	   size_t plaintext_len = strlen(plaintext_str);
78	
79	   // Use stack allocation instead of malloc
80	   uint8_t ciphertext[256]; // Buffer large enough for the plaintext
81	   uint8_t decrypted[256];  // Buffer large enough for the plaintext
82	   uint8_t auth_tag[16];
83	   // Encrypt
84	   int ret = chacha20poly1305_encrypt(
85	      ciphertext, auth_tag, key, nonce,
86	      plaintext, plaintext_len, aad, aad_len);
87	
88	   if (ret != 0)
89	   {
90	      return -1;
91	   }
92	   // Decrypt
93	   ret = chacha20poly1305_decrypt(
94	      decrypted, key, nonce, ciphertext, plaintext_len,
95	      auth_tag, aad, aad_len);
96	
97	   if (ret == 0)
98	   {
99	      uart_send(csr, "ChaCha20-Poly1305 test passed!\r\n");
100	   }
101	   else
102	   {
103	      uart_send(csr, "ChaCha20-Poly1305 test failed!\r\n");
104	      return -1;
105	   }
106	
107	   return 0;
108	}
