166	static void test_curve25519(volatile csr_vp_t* csr) {
167	   /* Simulate Alice and Bob doing a complete key exchange */
168	   uint8_t alice_private[32], bob_private[32];
169	   uint8_t alice_public[32], bob_public[32];
170	   uint8_t alice_shared[32], bob_shared[32];
171	
172	   // Generate private keys
173	   random_32bytes(alice_private);
174	   random_32bytes(bob_private);
175	
176	   // Generate public keys
177	   int alice_keygen = curve25519_generate_public_key(alice_public, alice_private);
178	   int bob_keygen = curve25519_generate_public_key(bob_public, bob_private);
179	
180	   // Exchange public keys and compute shared secrets
181	   int alice_shared_result = curve25519_compute_shared_secret(alice_shared, alice_private, bob_public);
182	   int bob_shared_result = curve25519_compute_shared_secret(bob_shared, bob_private, alice_public);
183	
184	   // Verify shared secrets match
185	   int secrets_match = memcmp(alice_shared, bob_shared, 32) == 0;
186	
187	   if (secrets_match) {
188	      uart_send(csr, "Key exchange successful! Alice and Bob have the same shared secret\r\n");
189	   } else {
190	      uart_send(csr, "Key exchange failed! Shared secrets don't match.\r\n");
191	   }
192	}
