784	int main(void) {
785	   volatile csr_vp_t* csr = new csr_vp_t();
786	   char uart_rx_data[UART_RXBUF_SIZE];
787	   uint8_t uart_rx_len;
788	   uint8_t debug_enabled = 0;
789	
790	   // Check hardware ID
791	   if (csr->hw_id->VENDOR() != 0xCCBA ||
792	       csr->hw_id->PRODUCT() != 0xCACA) {
793	      uart_send(csr, "\r\nHardware ID mismatch! Halting...\r\n");
794	      asm volatile ("ebreak");
795	   }
796	
797	   // Display banner
798	   uart_send(csr, "\r\n==========================================\r\n");
799	   uart_send(csr, "          WireGuard FPGA v");
800	   uart_send_dec(csr, csr->hw_version->MAJOR());
801	   uart_send_char(csr, '.');
802	   uart_send_dec(csr, csr->hw_version->MINOR());
803	   uart_send_char(csr, '.');
804	   uart_send_dec(csr, csr->hw_version->PATCH());
805	   uart_send(csr, "\r\n   Copyright \u00A9 2024-2026 Chili.CHIPS*ba\r\n");
806	   uart_send(csr, "==========================================\r\n");
807	
808	   // Boot sequence
809	   uart_send(csr, "Booting up...\r\n");
810	   init_network(csr, &net_config);
811	   show_network(csr, &net_config);
812	
813	   // CLI prompt
814	   uart_send(csr, "\r\nType 'help' to display commands.\r\n");
815	   uart_send(csr, "(wireguard-fpga)# ");
816	
817	   while (1) {
818	      // Receive Ethernet packet for CPU FIFO
819	      if (eth_receive_packet(csr, &eth_packet_rx)) {
820	         csr->gpio->led2(1);
821	         // Parse packet header
822	         net_protocol_t protocol = net_parse_packet_header(&eth_packet_rx);
823	         switch (protocol) {
824	            case NET_PROTO_UNKNOWN:
825	               if (debug_enabled) {
826	                  uart_send(csr, "<< NET_PROTO_UNKNOWN: ");
827	                  uart_send_dec(csr, eth_packet_rx.len);
828	                  uart_send(csr, "\r\n");
829	               }
830	               break;
831	            case NET_PROTO_ARP:
832	               if (debug_enabled) {
833	                  uart_send(csr, "<< NET_PROTO_ARP: ");
834	                  uart_send_dec(csr, eth_packet_rx.len);
835	                  uart_send(csr, "\r\n");
836	               }
837	               if (net_process_arp(&net_config, &net_arp_cache, &eth_packet_rx, &eth_packet_tx)) {
838	                  eth_send_packet(csr, &eth_packet_tx);
839	                  if (debug_enabled) {
840	                     uart_send(csr, ">> NET_PROTO_ARP: ");
841	                     uart_send_dec(csr, eth_packet_tx.len);
842	                     uart_send(csr, "\r\n");
843	                  }
844	               }
845	               break;
846	            case NET_PROTO_ICMP:
847	               if (debug_enabled) {
848	                  uart_send(csr, "<< NET_PROTO_ICMP: ");
849	                  uart_send_dec(csr, eth_packet_rx.len);
850	                  uart_send(csr, "\r\n");
851	               }
852	               if (net_process_icmp(&net_config, &eth_packet_rx, &eth_packet_tx)) {
853	                  eth_send_packet(csr, &eth_packet_tx);
854	                  if (debug_enabled) {
855	                     uart_send(csr, ">> NET_PROTO_ICMP: ");
856	                     uart_send_dec(csr, eth_packet_tx.len);
857	                     uart_send(csr, "\r\n");
858	                  }
859	               }
860	               break;
861	            case NET_PROTO_UDP:
862	               if (debug_enabled) {
863	                  uart_send(csr, "<< NET_PROTO_UDP: ");
864	                  uart_send_dec(csr, eth_packet_rx.len);
865	                  uart_send(csr, "\r\n");
866	               }
