external regfile routing_table {
   name = "csr.routing_table";
   desc = "Routing Table";

   typedef enum logic [3:0] {
      IDLE,
      R0, S0,
      R1, S1,
      R2, S2,
      R3, S3,
      R4, S4
   } state_t;

   state_t state, next_state;

   dpe_if to_dpe_sbuff(.clk(from_cpu.clk), .rst(from_cpu.rst));

// FSM registers
   always_ff @(posedge from_cpu.clk) begin
      if (from_cpu.rst) begin
         state <= IDLE;
      end else begin
         state <= next_state;
      end
   end

// FSM transition logic
   always_comb begin
      next_state = state;

      unique case (state)
         IDLE: begin
            if (!pause) next_state = R0;
         end

         R0: begin
            if (from_cpu.tvalid && to_dpe_sbuff.tready)       next_state = S0;
            else if (pause)                                   next_state = IDLE;

